function applyLang(){
 $$('[data-t]').forEach(el=>{el.innerHTML=IF.tr(el.dataset.t);});
 $$('[data-tp]').forEach(el=>{el.placeholder=IF.tr(el.dataset.tp);});
 $$('[data-lang]').forEach(b=>b.classList.toggle('on',b.dataset.lang===IF.lang));
 document.documentElement.lang=IF.lang;$('#langSel').value=IF.lang;document.documentElement.dir=IF.lang==='ar'?'rtl':'ltr';
 {const dc=$('#draftChip');const d=T[IF.lang].draft;dc.hidden=!d;dc.textContent=d||'';}
 try{localStorage.setItem('if_lang',IF.lang);}catch(e){}
 if(IF.relayout)IF.relayout();
 if(zoomFrom)$('#zEyebrow').textContent=IF.tr(zoomFrom.dataset.k);
 updateWho();rebuildLens();if(IF.setInds)IF.setInds();
 if(!cat.hidden)renderCat();
}
$$('[data-lang]').forEach(b=>b.addEventListener('click',()=>{IF.lang=b.dataset.lang;applyLang();}));
$('#langSel').addEventListener('change',e=>{IF.lang=e.target.value;applyLang();});

function resize(){IF.W=stage.clientWidth;IF.H=stage.clientHeight;lensDom.style.width=IF.W+'px';lensDom.style.height=IF.H+'px';
 if(IF.mode==='compare'){IF.cmpX=clamp(IF.cmpX,40,IF.W-40);applyCompare();}
 if(zoomFrom&&zoom.classList.contains('open')){fitZoom();setTimeout(()=>IF.setInds&&IF.setInds(),600);}}
new ResizeObserver(resize).observe(stage);

/* lens clones */
function cloneLayer(el){const c=el.cloneNode(true);c.removeAttribute('id');c.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));const z=c.querySelector('.zoom');if(z)z.remove();c.setAttribute('inert','');c.setAttribute('aria-hidden','true');return c;}
function rebuildLens(){
 lensDom.innerHTML='';lensPub=lensPro=null;
 if(pubUI.style.visibility!=='hidden'){lensPub=cloneLayer(pubUI);lensDom.appendChild(lensPub);}
 if(!pro.hidden){lensPro=cloneLayer(pro);lensDom.appendChild(lensPro);}
}
function syncLens(){
 if(lensPub){if(lensPub.className!==pubUI.className)lensPub.className=pubUI.className;if(lensPub.style.clipPath!==pubUI.style.clipPath)lensPub.style.clipPath=pubUI.style.clipPath;}
 if(lensPro){if(lensPro.className!==pro.className)lensPro.className=pro.className;if(lensPro.style.clipPath!==pro.style.clipPath)lensPro.style.clipPath=pro.style.clipPath;}
}

/* pointer */
stage.addEventListener('pointermove',e=>{
 const r=stage.getBoundingClientRect(),P=IF.ptr;P.x=e.clientX-r.left;P.y=e.clientY-r.top;P.in=true;P.touch=e.pointerType!=='mouse';
 const m=e.target.closest('[data-magnet]');
 if(m!==(magnet&&magnet.el)){if(magnet)magnet.el.style.transform='';magnet=null;
  if(m&&!P.touch){m.style.transform='';const b=m.getBoundingClientRect();magnet={el:m,x:b.left-r.left+b.width/2,y:b.top-r.top+b.height/2,h:b.height};}}
 if(magnet&&!reduce)magnet.el.style.transform='translate('+((P.x-magnet.x)*.16).toFixed(1)+'px,'+((P.y-magnet.y)*.26).toFixed(1)+'px)';
});
let lgPend=false;
stage.addEventListener('pointermove',e=>{if(lgPend||IF.ptr.touch)return;lgPend=true;const cx=e.clientX,cy=e.clientY;const el=e.target.closest&&e.target.closest('.lg');requestAnimationFrame(()=>{lgPend=false;if(!el)return;const r=el.getBoundingClientRect();el.style.setProperty('--lx',((cx-r.left)/r.width*100).toFixed(1)+'%');el.style.setProperty('--ly',((cy-r.top)/r.height*100).toFixed(1)+'%');});});
stage.addEventListener('pointerleave',()=>{IF.ptr.in=false;if(magnet){magnet.el.style.transform='';magnet=null;}});
stage.addEventListener('pointerdown',e=>{
 if(IF.mode==='transition'||e.target.closest('.gate,.zoom,.divider'))return;
 const r=stage.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;
 IF.ptr.touch=e.pointerType!=='mouse';IF.ripples.push({x,y});
 const s=document.createElement('span');s.className='rip';s.style.left=x+'px';s.style.top=y+'px';
 s.addEventListener('animationend',()=>s.remove());stage.appendChild(s);
});

/* cards */
$$('.card').forEach(el=>{
 el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;el.style.setProperty('--mx',(x*100).toFixed(1)+'%');el.style.setProperty('--my',(y*100).toFixed(1)+'%');if(!reduce)el.style.transform='perspective(700px) rotateX('+((.5-y)*9).toFixed(2)+'deg) rotateY('+((x-.5)*11).toFixed(2)+'deg) translateY(-3px)';});
 el.addEventListener('pointerleave',()=>{el.style.transform='';});
 el.addEventListener('click',()=>{const k=el.dataset.k;if(k==='k1t')openPro('prod');else if(k==='k2t')openPro('docs');else if(k==='k3t')openPro('req');else openPro('docs',{dt:4});});
});

/* zoom */
function rectOf(el){const s=stage.getBoundingClientRect(),r=el.getBoundingClientRect();return{l:r.left-s.left,t:r.top-s.top,w:r.width,h:r.height};}
function setRect(o){zoom.style.left=o.l+'px';zoom.style.top=o.t+'px';zoom.style.width=o.w+'px';zoom.style.height=o.h+'px';}
function fitZoom(){const pad=IF.W<760?10:24;setRect({l:pad,t:pad,w:IF.W-pad*2,h:IF.H-pad*2});zoom.style.setProperty('--zh',(IF.H-pad*2)+'px');}
$('.z-in').addEventListener('scroll',e=>{zoom.classList.toggle('scrolled',e.currentTarget.scrollTop>4);},{passive:true});
function openZoom(card){
 if(IF.mode==='compare')return;
 zoomFrom=card;$('#zEyebrow').textContent=IF.tr(card.dataset.k);$('#zTitle').innerHTML='Regenflex <span>32 mg</span>';
 $('#mOk').hidden=true;$('#mErr').textContent='';
 card.style.transform='';setRect(rectOf(card));zoom.hidden=false;zoom.classList.remove('open');void zoom.offsetWidth;
 requestAnimationFrame(()=>{fitZoom();zoom.classList.add('open');IF.setInds();});
 setTimeout(()=>{$('#zClose').focus({preventScroll:true});IF.setInds();},reduce?0:600);
}
function closeZoom(instant){
 if(zoom.hidden)return;zoom.classList.remove('open');
 if(instant||!zoomFrom){zoom.hidden=true;zoomFrom=null;return;}
 setRect(rectOf(zoomFrom));const f=zoomFrom;zoomFrom=null;setTimeout(()=>{zoom.hidden=true;f.focus({preventScroll:true});},reduce?0:560);
}
$('#zClose').addEventListener('click',()=>closeZoom());
function setInd(seg){const on=seg.querySelector('button.on'),ind=seg.querySelector('.gseg-ind');if(!on||!ind)return;ind.style.width=on.offsetWidth+'px';ind.style.transform='translateX('+on.offsetLeft+'px)';}
IF.setInds=()=>{$$('.gseg').forEach(setInd);};
$$('#zTabs button').forEach(b=>b.addEventListener('click',()=>{
 $$('#zTabs button').forEach(x=>x.classList.toggle('on',x===b));setInd($('#zTabs'));
 $$('.tpane').forEach(p=>{const show=p.dataset.pane===b.dataset.tab;if(show&&p.hidden){p.hidden=false;p.style.animation='none';void p.offsetWidth;p.style.animation='';}else if(!show)p.hidden=true;});
}));
IF.prodView=0;IF.prodSpin=true;
$$('#pSeg button').forEach(b=>b.addEventListener('click',()=>{$$('#pSeg button').forEach(x=>x.classList.toggle('on',x===b));setInd($('#pSeg'));IF.prodView=+b.dataset.v;}));
$('#pSpin').addEventListener('click',e=>{IF.prodSpin=!IF.prodSpin;e.currentTarget.setAttribute('aria-pressed',IF.prodSpin);});
$$('[data-mailjump]').forEach(b=>b.addEventListener('click',()=>{const i=$('#zEmail');i.scrollIntoView({block:'center',behavior:reduce?'auto':'smooth'});setTimeout(()=>i.focus({preventScroll:true}),reduce?0:350);}));
$('#sOrg').addEventListener('input',()=>{$('#sErr').textContent='';});
$('#sForm').addEventListener('submit',e=>{e.preventDefault();if(!$('#sOrg').value.trim()){$('#sErr').textContent=IF.tr('e_org');$('#sOk').hidden=true;return;}$('#sErr').textContent='';const ok=$('#sOk');ok.textContent=IF.tr('s_ok');ok.hidden=false;});
['zEmail','zKvkk'].forEach(id=>$('#'+id).addEventListener('input',()=>{$('#mErr').textContent='';}));
$('#mailForm').addEventListener('submit',e=>{
 e.preventDefault();const v=$('#zEmail').value.trim();
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)){$('#mErr').textContent=IF.tr('e_mail');$('#mOk').hidden=true;return;}
 if(!$('#zKvkk').checked){$('#mErr').textContent=IF.tr('e_kvkk');$('#mOk').hidden=true;return;}
 $('#mErr').textContent='';const ok=$('#mOk');ok.textContent=IF.tr('m_ok').replace('{e}',v);ok.hidden=false;
});


