function openCat(){if(IF.mode==='public')location.href=IFU.ax(-1);return;IF.setFull&&IF.setFull(true);CS.mode='pub';CS.view='prod';CS.det=-1;showCat();}
function showCat(){cat.classList.toggle('pro-mode',CS.mode==='pro');renderCat();catBody.scrollTop=0;if(cat.hidden){cat.hidden=false;void cat.offsetWidth;cat.classList.add('open');}setTimeout(()=>$('#catClose').focus({preventScroll:true}),40);}
