function closeCat(instant){if(cat.hidden)return;cat.classList.remove('open');if(CS.mode==='pro')$$('#proNav button').forEach(b=>b.classList.toggle('on',b.dataset.pv==='home'));if(instant){cat.hidden=true;return;}if(IF.mode==='public'&&gate.hidden&&IF.setFull)IF.setFull(false);setTimeout(()=>{cat.hidden=true;},reduce?0:300);}
$$('#proNav button').forEach(b=>b.addEventListener('click',()=>openPro(b.dataset.pv)));
